import React, { StrictMode, useState } from 'react'
import { createRoot } from 'react-dom/client'
import {
  ArrowRight, Bell, CalendarDays, CarFront, Check, ChevronRight, CircleDollarSign,
  Clock3, Database, Download, Gift, LayoutDashboard, LogOut, Menu, MessageCircle, MoreHorizontal,
  Plus, ReceiptText, Settings2, ShieldCheck, Sparkles, Ticket, UserRound, Users, Wrench, X, Zap, PhoneCall
} from 'lucide-react'
import { claimReward, createBill, createBooking, createReward, createTimeSlot, createVehicle, createWalkinRequest, deleteReward, getAdminData, getAvailableSlots, getCustomerData, getProfile, markBillPaid, markNotificationsRead, normalizePhone, signInWithPhone, signUpWithPhone, supabase, updateBookingStatus, updateJobStatus, updateReward, updateTimeSlot, updateWorkshopStatus, validateReferralCode } from './lib/supabase'
import './styles.css'

const initialBookings = [
  { id: 'DM-1048', customer: 'Rahul Mehta', initials: 'RM', vehicle: 'Hyundai Creta', issue: 'Headlight flickering', date: 'Today, 10:00 AM', status: 'Confirmed', tone: 'blue' },
  { id: 'DM-1049', customer: 'Priya Shah', initials: 'PS', vehicle: 'Maruti Swift', issue: 'Battery drain overnight', date: 'Today, 11:00 AM', status: 'Pending', tone: 'orange' },
  { id: 'DM-1050', customer: 'Arjun Rao', initials: 'AR', vehicle: 'Tata Nexon', issue: 'AC not cooling', date: 'Tomorrow, 9:00 AM', status: 'Confirmed', tone: 'green' },
]
const initialJobs = [
  { id: 'JOB-2204', customer: 'Suresh Kumar', vehicle: 'Toyota Innova', issue: 'Starter motor replacement', status: 'Arrived', time: 'Since 09:42 AM' },
  { id: 'JOB-2203', customer: 'Anita Desai', vehicle: 'Honda City', issue: 'Alternator inspection', status: 'Confirmed', time: 'Today, 12:00 PM' },
  { id: 'JOB-2202', customer: 'Vikram Singh', vehicle: 'Mahindra XUV700', issue: 'Fuse and wiring repair', status: 'Completed', time: 'Yesterday' },
]
const initialBills = [
  { id: 'INV-2038', customer: 'Vikram Singh', service: 'Fuse & wiring repair', date: '02 Sep 2026', amount: 2450, status: 'Paid' },
  { id: 'INV-2037', customer: 'Neha Patel', service: 'Battery replacement', date: '01 Sep 2026', amount: 6800, status: 'Pending' },
]
const slots = ['09:00 AM - 10:00 AM', '10:00 AM - 11:00 AM', '11:00 AM - 12:00 PM', '01:00 PM - 02:00 PM', '02:00 PM - 03:00 PM']

function Logo({ compact = false }) {
  return <div className={`brand-lockup ${compact ? 'compact' : ''}`}><span className="brand-mark"><Zap size={compact ? 16 : 20} fill="currentColor" /></span><span><strong>DHARMA</strong><small>MOTORS</small></span></div>
}

function App() {
  const [session, setSession] = useState(null)
  const [profile, setProfile] = useState(null)
  const [authLoading, setAuthLoading] = useState(true)
  const [customerView, setCustomerView] = useState('overview')
  const [adminView, setAdminView] = useState('overview')
  const [mobileNav, setMobileNav] = useState(false)
  const [toast, setToast] = useState('')
  const [bookings, setBookings] = useState([])
  const [jobs, setJobs] = useState([])
  const [bills, setBills] = useState([])
  const [points, setPoints] = useState(0)
  const [showBooking, setShowBooking] = useState(false)
  const [showVehicle, setShowVehicle] = useState(false)
  const [showBill, setShowBill] = useState(false)
  const [billJob, setBillJob] = useState(null)
  const [billDraft, setBillDraft] = useState({ parts: 0, service: 0, scanning: 0 })
  const [showReward, setShowReward] = useState(false)
  const [editingReward, setEditingReward] = useState(null)
  const [showSlot, setShowSlot] = useState(false)
  const [vehicles, setVehicles] = useState([])
  const [availableSlots, setAvailableSlots] = useState([])
  const [timeSlots, setTimeSlots] = useState([])
  const [customerLoading, setCustomerLoading] = useState(false)
  const [adminLoading, setAdminLoading] = useState(false)
  const [appointmentsOpen, setAppointmentsOpen] = useState(true)
  const [customers, setCustomers] = useState([])
  const [rewards, setRewards] = useState([])
  const [rewardClaims, setRewardClaims] = useState([])
  const [customerClaims, setCustomerClaims] = useState([])
  const [dataError, setDataError] = useState('')
  const [notifications, setNotifications] = useState([])
  const [notificationsOpen, setNotificationsOpen] = useState(false)
  const [installPrompt, setInstallPrompt] = useState(null)
  const [showInstallBar, setShowInstallBar] = useState(false)
  const [isIosInstall, setIsIosInstall] = useState(false)
  const [showIosGuide, setShowIosGuide] = useState(false)

  const notify = (message) => { setToast(message); window.setTimeout(() => setToast(''), 2800) }
  const customerNav = [{ key: 'overview', label: 'Overview', icon: LayoutDashboard }, { key: 'bookings', label: 'My bookings', icon: CalendarDays }, { key: 'bills', label: 'My bills', icon: ReceiptText }, { key: 'rewards', label: 'Rewards', icon: Gift }, { key: 'refer', label: 'Refer & earn', icon: Users }]
  const adminNav = [{ key: 'overview', label: 'Dashboard', icon: LayoutDashboard }, { key: 'appointments', label: 'Appointments', icon: CalendarDays }, { key: 'jobs', label: 'Jobs', icon: Wrench }, { key: 'bills', label: 'Bills', icon: ReceiptText }, { key: 'customers', label: 'Customers', icon: Users }, { key: 'rewards', label: 'Rewards', icon: Gift }, { key: 'slots', label: 'Time slots', icon: Clock3 }]
  const mode = profile?.role === 'admin' ? 'admin' : 'customer'
  const nav = mode === 'customer' ? customerNav : adminNav
  const view = mode === 'customer' ? customerView : adminView
  const setView = mode === 'customer' ? setCustomerView : setAdminView

  React.useEffect(() => {
    const isStandalone = window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true
    const isIos = /iPad|iPhone|iPod/.test(window.navigator.userAgent)
    const dismissed = window.localStorage.getItem('dharma-install-dismissed') === 'true'
    if (isStandalone || dismissed) return undefined
    if (isIos) { setIsIosInstall(true); setShowInstallBar(true) }
    const onBeforeInstall = event => { event.preventDefault(); setInstallPrompt(event); setShowInstallBar(true) }
    window.addEventListener('beforeinstallprompt', onBeforeInstall)
    return () => window.removeEventListener('beforeinstallprompt', onBeforeInstall)
  }, [])

  const dismissInstallBar = () => { window.localStorage.setItem('dharma-install-dismissed', 'true'); setShowInstallBar(false); setShowIosGuide(false) }
  const installApp = async () => {
    if (isIosInstall) return setShowIosGuide(!showIosGuide)
    if (!installPrompt) return
    installPrompt.prompt()
    await installPrompt.userChoice
    setInstallPrompt(null); setShowInstallBar(false)
  }

  const refreshAdminData = async () => {
    const data = await getAdminData()
    setBookings(data.bookings.map(booking => ({ id: booking.id, customer: booking.profiles?.full_name || 'Customer', phone: booking.profiles?.phone, initials: (booking.profiles?.full_name || 'CU').split(' ').map(part => part[0]).join('').slice(0, 2), vehicle: booking.vehicles?.model_name || 'Vehicle', issue: booking.problem, date: `${new Date(booking.appointment_date).toLocaleDateString('en-IN', { day: '2-digit', month: 'short' })} · ${booking.time_slots?.label || ''}`, status: booking.status[0].toUpperCase() + booking.status.slice(1), tone: 'blue' })))
    setJobs(data.jobs.map(job => ({ id: job.id, bookingId: job.booking_id, customerId: job.customer_id, customer: job.profiles?.full_name || 'Customer', phone: job.profiles?.phone, referredBy: job.profiles?.referred_by, referrerName: job.referrer_name, referralEligible: job.referral_eligible, vehicle: job.vehicles?.model_name || 'Vehicle', issue: job.problem, status: job.status[0].toUpperCase() + job.status.slice(1), time: new Date(job.created_at).toLocaleDateString('en-IN') })))
    setBills(data.bills.map(bill => ({ id: bill.id, customer: bill.profiles?.full_name || 'Customer', service: bill.work_done, date: new Date(bill.created_at).toLocaleDateString('en-IN'), amount: Number(bill.total || 0), status: bill.status === 'paid' ? 'Paid' : 'Pending', customerId: bill.customer_id })))
    setCustomers(data.customers); setRewards(data.rewards); setRewardClaims(data.claims); setTimeSlots(data.slots); setAppointmentsOpen(data.appointmentsOpen)
  }

  React.useEffect(() => {
    if (!session || mode !== 'customer') return undefined
    setVehicles([])
    setBookings([])
    setBills([])
    setCustomerLoading(true)
    setDataError('')
    let mounted = true
    const refreshCustomerData = async () => {
      try {
        const data = await getCustomerData(session.user.id)
        if (!mounted) return
      setVehicles(data.vehicles)
      setBookings(data.bookings)
      setBills(data.bills)
      setAvailableSlots(data.slots)
      setAppointmentsOpen(data.appointmentsOpen)
      setRewards(data.rewards)
      setCustomerClaims(data.claims)
      setNotifications(data.notifications)
      const { data: freshProfile } = await getProfile(session.user.id)
      if (freshProfile) setProfile(freshProfile)
      setCustomerLoading(false)
      } catch (error) {
        if (mounted) { setDataError(error.message); setCustomerLoading(false) }
      }
    }
    refreshCustomerData()
    const channel = supabase?.channel(`customer-bookings-${session.user.id}`)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'bookings', filter: `customer_id=eq.${session.user.id}` }, refreshCustomerData)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'bills', filter: `customer_id=eq.${session.user.id}` }, refreshCustomerData)
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'notifications', filter: `customer_id=eq.${session.user.id}` }, refreshCustomerData)
      .subscribe()
    const interval = window.setInterval(refreshCustomerData, 30000)
    const onFocus = () => refreshCustomerData()
    window.addEventListener('focus', onFocus)
    return () => { mounted = false; window.clearInterval(interval); window.removeEventListener('focus', onFocus); if (channel) supabase?.removeChannel(channel) }
  }, [session, mode])

  React.useEffect(() => {
    if (!session || mode !== 'admin') return undefined
    setAdminLoading(true)
    setDataError('')
    refreshAdminData().then(() => setAdminLoading(false)).catch(error => { setDataError(error.message); setAdminLoading(false) })
    return undefined
  }, [session, mode])

  const addBooking = async (event) => {
    event.preventDefault()
    const form = new FormData(event.currentTarget)
    const result = await createBooking(session.user.id, { vehicle_id: form.get('vehicleId'), slot_id: form.get('slotId'), appointment_date: form.get('date'), problem: form.get('problem') })
    if (result.error) return notify('That appointment slot is no longer available. Please choose another time.')
    setShowBooking(false); notify('Appointment requested successfully')
    const data = await getCustomerData(session.user.id); setBookings(data.bookings)
  }
  const addVehicle = async (event) => {
    event.preventDefault()
    const form = new FormData(event.currentTarget)
    const result = await createVehicle(session.user.id, { model_name: form.get('modelName'), type: form.get('type'), fuel: form.get('fuel') })
    if (result.error) return notify(result.error.message)
    setVehicles([result.data, ...vehicles]); setShowVehicle(false); notify('Vehicle added to your garage')
  }
  const markPaid = async (id) => { const result = await markBillPaid(id); if (result.error) return notify(result.error.message); await refreshAdminData(); notify('Bill marked paid. Customer points updated.') }
  const updateJob = async (id, status) => { const result = await updateJobStatus(id, status.toLowerCase()); if (result.error) return notify(result.error.message); setJobs(jobs.map(job => job.id === id ? { ...job, status } : job)); notify(`Job moved to ${status}`) }
  const openBillForJob = (job) => { setBillJob(job); setBillDraft({ parts: 0, service: 0, scanning: 0 }); setShowBill(true) }
  const updateAppointment = async (id, status) => { const result = await updateBookingStatus(id, status.toLowerCase()); if (result.error) return notify(result.error.message); const completedJob = jobs.find(job => job.bookingId === id); await refreshAdminData(); if (status === 'Completed') { if (completedJob) openBillForJob({ ...completedJob, status: 'Completed' }); setAdminView('jobs') } notify(`Appointment ${status.toLowerCase()}`) }
  const updateSlot = async (id, updates) => { const result = await updateTimeSlot(id, updates); if (result.error) return notify('Could not update this time slot.'); await refreshAdminData(); notify('Time slot updated') }
  const toggleAppointments = async () => { const result = await updateWorkshopStatus(!appointmentsOpen); if (result.error) return notify(result.error.message); setAppointmentsOpen(!appointmentsOpen); notify(`Appointments ${!appointmentsOpen ? 'opened' : 'closed'}`) }
  const handleClaim = async (reward) => { const result = await claimReward(session.user.id, reward.id, reward.points_required); if (result.error) return notify(result.error.message); setProfile({ ...profile, points: Math.max(0, (profile.points || 0) - reward.points_required) }); notify('Reward claimed. Dharma Motors can now see it.') }

  React.useEffect(() => {
    if (!supabase) { setAuthLoading(false); return undefined }
    let mounted = true
    supabase.auth.getSession().then(async ({ data }) => {
      if (!mounted) return
      setSession(data.session)
      if (data.session) {
        const { data: account } = await getProfile(data.session.user.id)
        if (mounted) setProfile(account)
      }
      if (mounted) setAuthLoading(false)
    })
    const { data: listener } = supabase.auth.onAuthStateChange(async (_event, nextSession) => {
      setSession(nextSession)
      if (nextSession) {
        const { data: account } = await getProfile(nextSession.user.id)
        if (mounted) setProfile(account)
      } else if (mounted) setProfile(null)
    })
    return () => { mounted = false; listener.subscription.unsubscribe() }
  }, [])

  if (authLoading) return <div className="auth-loading"><Logo /><span>Loading your secure garage...</span></div>
  if (!session || !profile) return <AuthScreen onAuthenticated={(nextSession, account) => { setSession(nextSession); setProfile(account) }} />

  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav ? 'open' : ''}`}>
      <div className="sidebar-top"><Logo compact /><button className="icon-button mobile-close" onClick={() => setMobileNav(false)}><X size={18} /></button></div>
      <div className="workspace-switch"><span className="avatar avatar-blue">{mode === 'customer' ? (profile.full_name || 'C').split(' ').map(part => part[0]).join('').slice(0, 2) : 'DM'}</span><span><strong>{mode === 'customer' ? profile.full_name : 'Dharma Motors'}</strong><small>{mode === 'customer' ? 'Customer account' : 'Admin workspace'}</small></span><ChevronRight size={16} /></div>
      <nav className="main-nav">{nav.map(item => { const Icon = item.icon; const pendingAppointments = bookings.filter(booking => booking.status === 'Pending').length; return <button key={item.key} className={view === item.key ? 'active' : ''} onClick={() => { setView(item.key); setMobileNav(false) }}><Icon size={18} />{item.label}{item.key === 'appointments' && pendingAppointments > 0 && <span className="nav-count">{pendingAppointments}</span>}</button> })}</nav>
      <div className="sidebar-bottom">{mode === 'admin' && <button onClick={() => setAdminView('walkin')}><Plus size={17} />Walk-in customer</button>}<button onClick={() => window.open('https://wa.me/917837051412?text=Emergency%20vehicle%20help', '_blank')}><Settings2 size={17} />Emergency help</button><div className="sidebar-help"><ShieldCheck size={19} /><span><strong>{mode === 'customer' ? 'Need assistance?' : 'Workshop health'}</strong><small>{mode === 'customer' ? 'Emergency: 7837051412' : 'All systems operational'}</small></span></div></div>
    </aside>
    {mobileNav && <div className="scrim" onClick={() => setMobileNav(false)} />}
    <main className="main-content">
      <header className="topbar"><button className="icon-button menu-button" onClick={() => setMobileNav(true)}><Menu size={20} /></button><div className="breadcrumbs"><span>{mode === 'customer' ? 'Customer portal' : 'Admin dashboard'}</span><ChevronRight size={14} /><strong>{nav.find(item => item.key === view)?.label}</strong></div><div className="topbar-actions"><div className="notification-wrap"><button className="icon-button notification" aria-label="Notifications" onClick={async () => { const nextOpen = !notificationsOpen; setNotificationsOpen(nextOpen); if (nextOpen) { const unread = notifications.filter(item => !item.read_at).map(item => item.id); await markNotificationsRead(unread); setNotifications(notifications.map(item => ({ ...item, read_at: item.read_at || new Date().toISOString() }))) } }}><Bell size={18} />{mode === 'customer' && notifications.some(item => !item.read_at) && <i />}</button>{notificationsOpen && <NotificationPanel notifications={notifications} />}</div><div className="user-chip"><span className="avatar avatar-dark">{(profile.full_name || 'DM').split(' ').map(part => part[0]).join('').slice(0, 2)}</span><span>{profile.full_name}</span></div><button className="icon-button" onClick={async () => { await supabase?.auth.signOut(); setSession(null); setProfile(null) }}><LogOut size={17} /></button></div></header>
      <div className="page-wrap">{mode === 'customer' && showInstallBar && <InstallBar isIos={isIosInstall} showIosGuide={showIosGuide} onInstall={installApp} onDismiss={dismissInstallBar} />}{dataError ? <DatabaseSetupState onRetry={() => setSession({ ...session })} /> : mode === 'customer' ? <CustomerView view={view} profile={profile} points={profile.points ?? 0} rewards={rewards} vehicles={vehicles} bookings={bookings} bills={bills} loading={customerLoading} appointmentsOpen={appointmentsOpen} setView={setView} onBook={() => appointmentsOpen && setShowBooking(true)} onVehicle={() => setShowVehicle(true)} onClaim={handleClaim} notify={notify} /> : <AdminView view={view} bookings={bookings} jobs={jobs} bills={bills} customers={customers} rewards={rewards} rewardClaims={rewardClaims} timeSlots={timeSlots} appointmentsOpen={appointmentsOpen} onToggleAppointments={toggleAppointments} setView={setView} onBill={() => setShowBill(true)} onOpenBill={openBillForJob} onReward={() => setShowReward(true)} onEditReward={setEditingReward} onSlot={() => setShowSlot(true)} onUpdateSlot={updateSlot} onWalkin={() => setAdminView('walkin')} onPaid={markPaid} onJob={updateJob} onAppointment={updateAppointment} notify={notify} />}</div>
    </main>
    {showBooking && <Modal title="Book an appointment" onClose={() => setShowBooking(false)}><form onSubmit={addBooking}><Field label="Select vehicle"><select name="vehicleId" required>{vehicles.length ? vehicles.map(vehicle => <option value={vehicle.id} key={vehicle.id}>{vehicle.model_name} · {vehicle.fuel}</option>) : <option value="">Add a vehicle first</option>}</select></Field><Field label="What needs attention?"><input name="problem" placeholder="e.g. Headlights flickering" required /></Field><div className="form-grid"><Field label="Preferred date"><input name="date" type="date" min={new Date().toISOString().slice(0, 10)} required onChange={async event => { const result = await getAvailableSlots(event.currentTarget.value); setAvailableSlots(result.data || []); if (result.error) notify('Could not load available time slots.') }} /></Field><Field label="Time slot"><select name="slotId" required disabled={!availableSlots.length}><option value="">{availableSlots.length ? 'Choose a slot' : 'Choose a date first'}</option>{availableSlots.map(slot => <option value={slot.id} key={slot.id}>{slot.label}</option>)}</select></Field></div><FormActions onCancel={() => setShowBooking(false)} submit="Request appointment" /></form></Modal>}
    {showVehicle && <Modal title="Add a vehicle" onClose={() => setShowVehicle(false)}><form onSubmit={addVehicle}><Field label="Model name"><input name="modelName" placeholder="e.g. Hyundai Creta" required /></Field><div className="form-grid"><Field label="Vehicle type"><select name="type"><option value="car">Car</option><option value="suv">SUV</option><option value="truck">Truck</option></select></Field><Field label="Fuel"><select name="fuel"><option value="petrol">Petrol</option><option value="diesel">Diesel</option></select></Field></div><FormActions onCancel={() => setShowVehicle(false)} submit="Add vehicle" /></form></Modal>}
    {showBill && <Modal title="Create bill" onClose={() => { setShowBill(false); setBillJob(null) }}><form onSubmit={async (event) => { event.preventDefault(); const form = new FormData(event.currentTarget); const job = billJob || jobs.find(item => item.id === form.get('jobId')); if (!job) return notify('Select a completed job before creating a bill.'); const parts = Number(form.get('parts') || 0); const service = Number(form.get('service') || 0); const scanning = Number(form.get('scanning') || 0); const total = parts + service + scanning; const result = await createBill({ job_id: job.id, customer_id: job.customerId, work_done: form.get('workDone') || job.issue || 'Service completed', spare_parts: parts, service_charge: service, scanning_cost: scanning }); if (result.error) return notify(result.error.code === '23505' ? 'A bill already exists for this job.' : 'Could not create this bill. Please try again.'); await refreshAdminData(); setShowBill(false); setBillJob(null); setAdminView('bills'); notify(`Bill created. Mark it paid to award ${Math.floor(total / 100) * 10} customer points${total >= 500 && job.referralEligible ? ', plus the one-time referral bonus.' : ''}`) }}><div className="bill-customer"><strong>{billJob?.customer || 'Select completed job'}</strong>{billJob?.phone && <a href={`tel:${billJob.phone}`}>{billJob.phone}</a>}{billJob?.referralEligible && <small>Referral reward pending: referred by {billJob.referrerName}. On this first ₹500+ paid bill, {billJob.customer} gets +100 points and {billJob.referrerName} gets +200 points.</small>}{billJob?.referredBy && !billJob?.referralEligible && <small>Referred by {billJob.referrerName} · referral bonus already used.</small>}</div>{!billJob && <Field label="Completed job"><select name="jobId" required defaultValue=""> <option value="" disabled>Select a completed job</option>{jobs.filter(job => job.status === 'Completed').map(job => <option value={job.id} key={job.id}>{job.customer} · {job.vehicle}{job.referralEligible ? ' · Referral bonus pending' : ''}</option>)}</select></Field>}<Field label="Work done (optional)"><textarea name="workDone" placeholder="Describe the repair completed" /></Field><div className="form-grid"><Field label="Spare parts (optional)"><input name="parts" type="number" min="0" placeholder="0" onInput={event => setBillDraft({ ...billDraft, parts: Number(event.currentTarget.value || 0) })} /></Field><Field label="Service charge (optional)"><input name="service" type="number" min="0" placeholder="0" onInput={event => setBillDraft({ ...billDraft, service: Number(event.currentTarget.value || 0) })} /></Field></div><Field label="Scanning cost (optional)"><input name="scanning" type="number" min="0" placeholder="0" onInput={event => setBillDraft({ ...billDraft, scanning: Number(event.currentTarget.value || 0) })} /></Field><div className="points-preview">Total: <strong>₹{(billDraft.parts + billDraft.service + billDraft.scanning).toLocaleString()}</strong> · Points after payment: <strong>{Math.floor((billDraft.parts + billDraft.service + billDraft.scanning) / 100) * 10}</strong>{billJob?.referralEligible && billDraft.parts + billDraft.service + billDraft.scanning >= 500 && <small> · First referral bill: +200 referrer, +100 customer</small>}</div><FormActions onCancel={() => { setShowBill(false); setBillJob(null) }} submit="Generate bill" /></form></Modal>}
    {showReward && <Modal title="Create reward" onClose={() => setShowReward(false)}><form onSubmit={async (event) => { event.preventDefault(); const form = new FormData(event.currentTarget); const result = await createReward({ name: form.get('name'), description: form.get('description'), points_required: Number(form.get('points')) }); if (result.error) return notify(result.error.message); setShowReward(false); notify('Reward created') }}><Field label="Reward name"><input name="name" placeholder="e.g. Free diagnostic scan" required /></Field><Field label="Description"><textarea name="description" placeholder="What does the customer receive?" required /></Field><Field label="Points required"><input name="points" type="number" min="1" placeholder="1000" required /></Field><FormActions onCancel={() => setShowReward(false)} submit="Create reward" /></form></Modal>}
    {editingReward && <Modal title="Edit reward" onClose={() => setEditingReward(null)}><form onSubmit={async event => { event.preventDefault(); const form = new FormData(event.currentTarget); const result = await updateReward(editingReward.id, { name: form.get('name'), description: form.get('description'), points_required: Number(form.get('points')), enabled: form.get('enabled') === 'true' }); if (result.error) return notify('Could not save this reward.'); await refreshAdminData(); setEditingReward(null); notify('Reward updated') }}><Field label="Reward name"><input name="name" defaultValue={editingReward.name} required /></Field><Field label="Description"><textarea name="description" defaultValue={editingReward.description} required /></Field><Field label="Points required"><input name="points" type="number" min="1" defaultValue={editingReward.points_required} required /></Field><Field label="Availability"><select name="enabled" defaultValue={String(editingReward.enabled)}><option value="true">Available to customers</option><option value="false">Hidden from customers</option></select></Field><div className="form-actions"><button className="button button-danger" type="button" onClick={async () => { if (!window.confirm(`Delete “${editingReward.name}”? This cannot be undone.`)) return; const result = await deleteReward(editingReward.id); if (result.error) return notify('This reward has claims, so hide it instead of deleting it.'); await refreshAdminData(); setEditingReward(null); notify('Reward deleted') }}>Delete reward</button><button className="button button-primary" type="submit">Save changes <ArrowRight size={16} /></button></div></form></Modal>}
    {showSlot && <Modal title="Add time slot" onClose={() => setShowSlot(false)}><form onSubmit={async (event) => { event.preventDefault(); const form = new FormData(event.currentTarget); const result = await createTimeSlot({ label: form.get('label'), max_bookings: Number(form.get('capacity')) }); if (result.error) return notify('That time slot already exists or could not be created.'); await refreshAdminData(); setShowSlot(false); notify('Time slot added') }}><Field label="Time slot"><input name="label" placeholder="03:00 PM - 04:00 PM" required /></Field><Field label="Maximum bookings"><input name="capacity" type="number" min="1" defaultValue="1" required /></Field><FormActions onCancel={() => setShowSlot(false)} submit="Add time slot" /></form></Modal>}
    {toast && <div className="toast"><Check size={16} />{toast}</div>}
  </div>
}

function AuthScreen({ onAuthenticated }) {
  const [registering, setRegistering] = useState(false)
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)
  const submit = async (event) => {
    event.preventDefault(); setError(''); setBusy(true)
    try {
      const form = new FormData(event.currentTarget)
      const password = String(form.get('password') || '')
      if (password.length < 6) {
        setError('Password must be at least 6 characters.')
        return
      }
      const enteredReferralCode = String(form.get('referralCode') || '')
      if (registering && enteredReferralCode.trim()) {
        const referral = await validateReferralCode(enteredReferralCode)
        if (referral.error) { setError('We could not verify that referral code. Please try again.'); return }
        if (!referral.valid) { setError('That referral code is not valid. Ask your friend to share their exact code.'); return }
      }
      const result = registering
        ? await signUpWithPhone({ name: form.get('name'), phone: form.get('phone'), password, referralCode: enteredReferralCode })
        : await signInWithPhone(form.get('phone'), password)
      if (result.error) {
        setError(registering
          ? 'We could not create your account. Check the details and try again, or use a different mobile number.'
          : 'The mobile number or password is incorrect. Please try again.')
      }
      else if (result.data?.session) {
        const { data: account, error: profileError } = await getProfile(result.data.session.user.id)
        if (profileError) setError('Your account is still being prepared. Please wait a moment and sign in again.')
        else if (account.role !== 'admin' && form.get('phone') === '7696707446') setError('This account does not have workshop access.')
        else onAuthenticated(result.data.session, account)
      } else if (registering) setError('Account created. Turn off Confirm email in Supabase, then sign in with your mobile number.')
    } catch (authError) {
      setError('We could not sign you in right now. Please try again shortly.')
    } finally {
      setBusy(false)
    }
  }
  return <div className="auth-screen"><div className="auth-brand"><Logo /><span className="auth-tagline">Auto Electrical Specialists</span></div><div className="auth-layout"><div className="auth-intro"><span className="eyebrow light">PRECISION THAT MOVES YOU</span><h1>Electrical care,<br /><em>without the guesswork.</em></h1><p>Vehicle electrical diagnostics, wiring repairs, alternators, starters, batteries and computer scanning—handled by specialists.</p><div className="auth-points"><span><ShieldCheck size={17} /> Certified electrical specialists</span><span><Clock3 size={17} /> Transparent service updates</span><span><Sparkles size={17} /> Rewards on every paid bill</span></div></div><div className="auth-card"><div className="auth-card-head"><span className="auth-kicker">WELCOME TO DHARMA MOTORS</span><h2>{registering ? 'Create your account' : 'Sign in to your garage'}</h2><p>{registering ? 'Use your mobile number to get started.' : 'Customers and workshop staff use secure sign in.'}</p></div><form onSubmit={submit}>{registering && <Field label="Full name"><input name="name" placeholder="e.g. Aarav Kapoor" required /></Field>}<Field label="Mobile number"><input name="phone" inputMode="tel" placeholder="10-digit mobile number" required /></Field><Field label="Password"><input name="password" type="password" placeholder="Enter your password" required /></Field>{registering && <Field label="Referral code (optional)"><input name="referralCode" placeholder="e.g. DM-AB12CD34" /></Field>}{error && <div className="auth-error">{error}</div>}<button className="button button-primary full-button" type="submit" disabled={busy}>{busy ? 'Checking...' : registering ? 'Create account' : 'Sign in'} {!busy && <ArrowRight size={16} />}</button></form><div className="auth-switch">{registering ? 'Already have an account?' : 'New to Dharma Motors?'} <button onClick={() => { setRegistering(!registering); setError('') }}>{registering ? 'Sign in' : 'Create an account'}</button></div></div></div><footer className="auth-footer"><Logo compact /><span>Trusted care for every connection.</span><small>© 2026 Dharma Motors</small></footer></div>
}

function CustomerView({ view, profile, points, rewards, vehicles, bookings, bills, loading, appointmentsOpen, setView, onBook, onVehicle, onClaim, notify }) {
  if (view === 'bookings') return <BookingsPage bookings={bookings} onBook={onBook} />
  if (view === 'bills') return <BillsPage bills={bills} notify={notify} />
  if (view === 'rewards') return <RewardsPage points={points} rewards={rewards} notify={notify} onClaim={onClaim} />
  if (view === 'refer') return <ReferPage code={profile.referral_code} notify={notify} />
  const firstName = (profile.full_name || 'Customer').split(' ')[0]
  const nextBooking = bookings.find(booking => !['Completed', 'Cancelled'].includes(booking.status)) || bookings[0]
  const nextReward = rewards.find(reward => reward.points_required > points)
  return <><PageHeader eyebrow="Your workshop account" title={`Hello, ${firstName}`} subtitle="Manage your vehicles and workshop visits in one place." action={appointmentsOpen ? 'Book appointment' : 'Appointments temporarily closed'} onAction={appointmentsOpen ? onBook : undefined} /><section className="hero-strip"><div><span className="eyebrow light">DHARMA MOTORS</span><h2>Electrical care made simple.</h2><p>{appointmentsOpen ? 'Electrical diagnostics & computer scanning, wiring repairs, alternators, starters and batteries.' : 'Online appointment booking is temporarily closed. You can still view your vehicles, bills, rewards and past appointments.'}</p>{appointmentsOpen ? <button className="button button-light" onClick={onBook}>Book a service <ArrowRight size={16} /></button> : <span className="appointments-closed-message"><Clock3 size={15} /> Booking will return when the workshop reopens appointments.</span>}</div><div className="hero-art"><CarFront size={130} strokeWidth={1} /><Zap className="hero-zap" size={30} fill="currentColor" /></div></section>{nextBooking && <AppointmentProgress booking={nextBooking} />}<section className="customer-highlight-grid"><PointsWallet points={points || 0} nextReward={nextReward} onRewards={() => setView('rewards')} /><Panel title="Quick actions"><div className="quick-grid">{appointmentsOpen ? <QuickAction icon={CalendarDays} label="Book service" onClick={onBook} /> : <div className="quick-action disabled-action"><span><CalendarDays size={19} /></span><strong>Appointments closed</strong></div>}<QuickAction icon={CarFront} label="Add vehicle" onClick={onVehicle} /><QuickAction icon={ReceiptText} label="My bills" onClick={() => setView('bills')} /></div></Panel></section><section className="stat-grid customer-stats"><Stat icon={CarFront} label="My vehicles" value={vehicles.length} note="Vehicles in your garage" tone="blue" /><Stat icon={CalendarDays} label="Appointments" value={bookings.length} note="Track each workshop visit" tone="gold" /><Stat icon={Sparkles} label="Reward points" value={(points || 0).toLocaleString()} note="Added after paid bills" tone="green" /></section><section className="contact-section"><div className="contact-section-heading"><span className="eyebrow">CONTACT DHARMA MOTORS</span><h3>Quick help when you need it</h3></div><div className="contact-grid"><article className="contact-card battery-contact"><div className="contact-card-icon"><Zap size={20} /></div><div><strong>Battery home delivery</strong><p>Car, home and inverter batteries delivered to you.</p><a className="contact-link" href="https://wa.me/917696707446?text=Hello%20Dharma%20Motors%2C%20I%20need%20a%20battery.%20It%20is%20for%3A">Order on WhatsApp <ArrowRight size={15} /></a></div></article><article className="contact-card emergency-contact"><div className="contact-card-icon"><PhoneCall size={20} /></div><div><strong>Vehicle not starting?</strong><p>Get urgent help for vehicle electrical problems.</p><div className="contact-actions"><a className="contact-link" href="tel:7837051412">Call emergency</a><a className="contact-link quiet" href="https://wa.me/917837051412?text=Hello%20Dharma%20Motors%2C%20I%20need%20urgent%20vehicle%20electrical%20help.">WhatsApp</a></div></div></article></div></section></>
}

  function AdminView({ view, bookings, jobs, bills, customers, rewards, rewardClaims, timeSlots, appointmentsOpen, onToggleAppointments, setView, onBill, onOpenBill, onReward, onEditReward, onSlot, onUpdateSlot, onWalkin, onPaid, onJob, onAppointment, notify }) {
  if (view === 'appointments') return <AppointmentsPage bookings={bookings} notify={notify} onWalkin={onWalkin} onAppointment={onAppointment} />
  if (view === 'jobs') return <JobsPage jobs={jobs} onJob={onJob} onBill={onOpenBill || onBill} />
  if (view === 'bills') return <BillsPage bills={bills} notify={notify} admin onPaid={onPaid} onBill={onBill} />
  if (view === 'customers') return <CustomersPage customers={customers} />
  if (view === 'rewards') return <AdminRewardsPage rewards={rewards} claims={rewardClaims} onReward={onReward} onEditReward={onEditReward} />
  if (view === 'slots') return <SlotsPage slots={timeSlots} notify={notify} onSlot={onSlot} onUpdateSlot={onUpdateSlot} />
  if (view === 'walkin') return <WalkinPage notify={notify} onCreate={async request => { const result = await createWalkinRequest(request); if (result.error) return notify(result.error.message); notify('Walk-in intake saved for the workshop') }} />
  if (view === 'overview') return <LiveAdminDashboard bookings={bookings} jobs={jobs} bills={bills} customers={customers} appointmentsOpen={appointmentsOpen} onToggleAppointments={onToggleAppointments} onWalkin={onWalkin} onAppointment={onAppointment} setView={setView} />
  return <><PageHeader eyebrow="Tuesday, 04 September 2026" title="Good morning, Dharma Motors" subtitle="Here is what is happening at the workshop today." action="Walk-in customer" onAction={() => setView('walkin')} /><section className="stat-grid admin-stats"><Stat icon={CalendarDays} label="Appointments today" value="08" note="3 awaiting confirmation" tone="blue" /><Stat icon={Wrench} label="Active jobs" value="05" note="2 ready for pickup" tone="orange" /><Stat icon={CircleDollarSign} label="Revenue today" value="₹12,850" note="↑ 18% vs last Tuesday" tone="green" /><Stat icon={Users} label="Total customers" value="248" note="+12 this month" tone="purple" /></section><div className="content-grid admin-content"><Panel title="Today's appointments" action="View all" onAction={() => setView('appointments')}><div className="booking-list">{bookings.map(booking => <BookingRow key={booking.id} booking={booking} admin notify={notify} />)}</div></Panel><Panel title="Live workshop floor" action="Manage jobs" onAction={() => setView('jobs')}><div className="floor-summary"><div className="floor-meter"><div className="meter-ring"><strong>05</strong><small>active jobs</small></div><div className="meter-legend"><span><i className="dot blue-dot" />Confirmed <b>2</b></span><span><i className="dot orange-dot" />Arrived <b>1</b></span><span><i className="dot green-dot" />Completed <b>2</b></span></div></div><div className="service-note"><Zap size={18} /><span><strong>Workshop is flowing well</strong><small>Average service time is 2h 15m today.</small></span></div></div></Panel></div><section className="admin-lower"><Panel title="Recent payments" action="Open bills" onAction={() => setView('bills')}><BillsTable bills={bills.slice(0, 2)} compact /></Panel><Panel title="Shortcuts"><div className="shortcut-list"><button onClick={onBill}><ReceiptText size={17} /><span><strong>Create a bill</strong><small>For a completed job</small></span><ArrowRight size={16} /></button><button onClick={() => setView('slots')}><Clock3 size={17} /><span><strong>Manage time slots</strong><small>5 active slots today</small></span><ArrowRight size={16} /></button></div></Panel></section></>
  return <><PageHeader eyebrow="Workshop control" title="Good morning, Dharma Motors" subtitle="Manage appointments, jobs, billing, and customer care." action="Walk-in customer" onAction={onWalkin} /><section className="workshop-control"><span className={`status-dot ${appointmentsOpen ? 'completed' : 'arrived'}`} /><strong>Appointments are {appointmentsOpen ? 'open' : 'closed'}</strong><small>{appointmentsOpen ? 'Customers can book new visits.' : 'Customers cannot book until you reopen them.'}</small><button className="small-button" onClick={onToggleAppointments}>{appointmentsOpen ? 'Close appointments' : 'Open appointments'}</button></section><section className="stat-grid admin-stats"><Stat icon={CalendarDays} label="Appointments" value={bookings.length} note="Live from Supabase" tone="blue" /><Stat icon={Wrench} label="Active jobs" value={jobs.filter(job => job.status !== 'Completed').length} note="Confirmed or arrived" tone="orange" /><Stat icon={CircleDollarSign} label="Paid bills" value={bills.filter(bill => bill.status === 'Paid').length} note="Live from Supabase" tone="green" /><Stat icon={Users} label="Customers" value={customers.length} note="Real customer profiles" tone="purple" /></section><div className="content-grid admin-content"><Panel title="Today's appointments" action="View all" onAction={() => setView('appointments')}><div className="booking-list">{bookings.slice(0, 3).map(booking => <BookingRow key={booking.id} booking={booking} admin onAppointment={onAppointment} />)}{!bookings.length && <EmptyState text="No appointments yet." />}</div></Panel><Panel title="Live workshop floor" action="Manage jobs" onAction={() => setView('jobs')}><div className="floor-summary"><div className="floor-meter"><div className="meter-ring"><strong>{jobs.filter(job => job.status !== 'Completed').length}</strong><small>active jobs</small></div><div className="meter-legend"><span><i className="dot blue-dot" />Confirmed <b>{jobs.filter(job => job.status === 'Confirmed').length}</b></span><span><i className="dot orange-dot" />Arrived <b>{jobs.filter(job => job.status === 'Arrived').length}</b></span><span><i className="dot green-dot" />Completed <b>{jobs.filter(job => job.status === 'Completed').length}</b></span></div></div></div></Panel></div><section className="admin-lower"><Panel title="Recent payments" action="Open bills" onAction={() => setView('bills')}><BillsTable bills={bills.slice(0, 2)} compact /></Panel><Panel title="Shortcuts"><div className="shortcut-list"><button onClick={onBill}><ReceiptText size={17} /><span><strong>Create a bill</strong><small>For a completed job</small></span><ArrowRight size={16} /></button><button onClick={onSlot}><Clock3 size={17} /><span><strong>Manage time slots</strong><small>Control booking capacity</small></span><ArrowRight size={16} /></button></div></Panel></section></>
}

function LiveAdminDashboard({ bookings, jobs, bills, customers, appointmentsOpen, onToggleAppointments, onWalkin, onAppointment, setView }) {
  const activeJobs = jobs.filter(job => job.status !== 'Completed').length
  const paidBills = bills.filter(bill => bill.status === 'Paid')
  const revenue = paidBills.reduce((total, bill) => total + bill.amount, 0)
  return <><PageHeader eyebrow="Workshop control" title="Good morning, Dharma Motors" subtitle="Live workshop activity and customer service status." action="Walk-in customer" onAction={onWalkin} /><section className="workshop-control"><span className={`status-dot ${appointmentsOpen ? 'completed' : 'arrived'}`} /><strong>Appointments are {appointmentsOpen ? 'open' : 'closed'}</strong><small>{appointmentsOpen ? 'Customers can book new visits.' : 'Customers cannot book until you reopen them.'}</small><button className="small-button" onClick={onToggleAppointments}>{appointmentsOpen ? 'Close appointments' : 'Open appointments'}</button></section><section className="stat-grid admin-stats"><Stat icon={CalendarDays} label="Appointments" value={bookings.length} note={bookings.filter(booking => booking.status === 'Pending').length ? `${bookings.filter(booking => booking.status === 'Pending').length} awaiting confirmation` : 'No pending confirmations'} tone="blue" /><Stat icon={Wrench} label="Active jobs" value={activeJobs} note={jobs.filter(job => job.status === 'Completed').length ? `${jobs.filter(job => job.status === 'Completed').length} completed` : 'No completed jobs yet'} tone="orange" /><Stat icon={CircleDollarSign} label="Paid revenue" value={`₹${revenue.toLocaleString('en-IN')}`} note={`${paidBills.length} paid bill${paidBills.length === 1 ? '' : 's'}`} tone="green" /><Stat icon={Users} label="Customers" value={customers.length} note="Live customer profiles" tone="purple" /></section><div className="content-grid admin-content"><Panel title="Recent appointments" action="View all" onAction={() => setView('appointments')}><div className="booking-list">{bookings.slice(0, 4).map(booking => <BookingRow key={booking.id} booking={booking} admin onAppointment={onAppointment} />)}{!bookings.length && <EmptyState text="No appointments yet." />}</div></Panel><Panel title="Workshop jobs" action="Manage jobs" onAction={() => setView('jobs')}><div className="floor-summary"><div className="floor-meter"><div className="meter-ring"><strong>{activeJobs}</strong><small>active jobs</small></div><div className="meter-legend"><span><i className="dot blue-dot" />Confirmed <b>{jobs.filter(job => job.status === 'Confirmed').length}</b></span><span><i className="dot orange-dot" />Arrived <b>{jobs.filter(job => job.status === 'Arrived').length}</b></span><span><i className="dot green-dot" />Completed <b>{jobs.filter(job => job.status === 'Completed').length}</b></span></div></div><div className="service-note"><Zap size={18} /><span><strong>{activeJobs ? 'Jobs are in progress' : 'Workshop ready for jobs'}</strong><small>{activeJobs ? 'Use the job board to update each service.' : 'Confirmed appointments will appear here.'}</small></span></div></div></Panel></div><section className="admin-lower"><Panel title="Recent payments" action="Open bills" onAction={() => setView('bills')}><BillsTable bills={bills.slice(0, 3)} compact /></Panel><Panel title="Shortcuts"><div className="shortcut-list"><button onClick={() => setView('jobs')}><ReceiptText size={17} /><span><strong>Completed jobs</strong><small>Create bills from a completed job</small></span><ArrowRight size={16} /></button><button onClick={() => setView('slots')}><Clock3 size={17} /><span><strong>Manage time slots</strong><small>Control booking capacity</small></span><ArrowRight size={16} /></button></div></Panel></section></>
}

function PageHeader({ eyebrow, title, subtitle, action, onAction }) { return <div className="page-header"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{subtitle}</p></div>{action && <button className="button button-primary" onClick={onAction} disabled={!onAction}><Plus size={17} />{action}</button>}</div> }
function InstallBar({ isIos, showIosGuide, onInstall, onDismiss }) { return <section className="install-bar"><img src="/icons/mechanic-192.png" alt="Dharma Motors mechanic" /><div className="install-copy"><strong>Install Dharma Motors</strong><span>Fast access from your home screen.</span>{showIosGuide && <small>Tap <b>Share</b> in Safari, then choose <b>Add to Home Screen</b>.</small>}</div><button className="install-button" onClick={onInstall}>{isIos ? 'How to install' : 'Install'} <Download size={14} /></button><button className="install-dismiss" aria-label="Dismiss install suggestion" onClick={onDismiss}><X size={16} /></button></section> }
function AdminRewardsPage({ rewards = [], claims = [], onReward, onEditReward }) { return <><PageHeader eyebrow="Retention engine" title="Rewards" subtitle="Create rewards, manage availability, and verify customer claim codes." action="Create reward" onAction={onReward} /><div className="reward-grid">{rewards.map(reward => <div className="reward-card" key={reward.id}><div className="reward-icon"><Gift size={20} /></div><span className="reward-tag">{reward.enabled ? 'LOYALTY REWARD · LIVE' : 'HIDDEN FROM CUSTOMERS'}</span><h3>{reward.name}</h3><p>{reward.description}</p><div className="reward-footer"><strong><Sparkles size={14} /> {reward.points_required.toLocaleString()} pts</strong><button className="small-button" onClick={() => onEditReward(reward)}>Edit reward</button></div></div>)}{!rewards.length && <EmptyState text="No rewards created yet." />}</div><Panel title="Recent reward claims"><div className="customer-list">{claims.map(claim => <div className="customer-row" key={claim.id}><div className="reward-icon"><Gift size={16} /></div><span><strong>{claim.profiles?.full_name || 'Customer'}</strong><small>{claim.rewards?.name || 'Reward'} · {new Date(claim.created_at).toLocaleDateString('en-IN')} · Claim code: <b>{claim.claim_code || 'Legacy claim'}</b></small></span><span className="customer-spend"><small>{claim.status}</small></span></div>)}{!claims.length && <EmptyState text="No reward claims yet." />}</div></Panel></> }
function Stat({ icon: Icon, label, value, note, tone }) { return <div className="stat-card"><div className={`stat-icon ${tone}`}><Icon size={19} /></div><div><span>{label}</span><strong>{value}</strong><small>{note}</small></div></div> }
function Panel({ title, action, onAction, children }) { return <section className="panel"><div className="panel-heading"><h3>{title}</h3>{action && <button className="text-button" onClick={onAction}>{action} <ArrowRight size={14} /></button>}</div>{children}</section> }
function BookingRow({ booking, admin, notify, onAppointment }) { return <div className="booking-row"><div className={`avatar avatar-${booking.tone}`}>{booking.initials}</div><div className="row-main"><strong>{booking.customer}</strong><span>{booking.vehicle} <i /> {booking.issue}{admin && booking.phone && <> <i /> {booking.phone}</>}</span></div><div className="row-meta"><strong>{booking.date}</strong><span className={`status ${booking.status.toLowerCase()}`}>{booking.status}</span></div>{admin && <div className="row-actions">{booking.status === 'Pending' && <button className="small-button" onClick={() => onAppointment(booking.id, 'Confirmed')}>Confirm</button>}{booking.status === 'Confirmed' && <button className="small-button" onClick={() => onAppointment(booking.id, 'Arrived')}>Arrived</button>}{booking.status === 'Arrived' && <button className="small-button" onClick={() => onAppointment(booking.id, 'Completed')}>Complete</button>}</div>}</div> }
function AppointmentProgress({ booking }) { const steps = ['Requested', 'Confirmed', 'At workshop', 'Service complete']; const current = { Pending: 0, Confirmed: 1, Arrived: 2, Completed: 3, Cancelled: 0 }[booking.status] ?? 0; if (booking.status === 'Completed') return <section className="appointment-progress service-complete"><div><span className="eyebrow">SERVICE COMPLETE</span><h3>{booking.vehicle}</h3><p>Your repair is complete. Your bill will appear here once the workshop issues it.</p></div><span className="status completed"><Check size={14} /> Complete</span></section>; if (booking.status === 'Cancelled') return null; return <section className="appointment-progress"><div><span className="eyebrow">CURRENT APPOINTMENT</span><h3>{booking.vehicle}</h3><p>{booking.issue} · {booking.date}</p></div><div className="progress-steps">{steps.map((step, index) => <span className={index <= current ? 'done' : ''} key={step}><i>{index < current ? <Check size={12} /> : index + 1}</i>{step}</span>)}</div></section> }
function PointsWallet({ points, nextReward, onRewards }) { const remaining = nextReward ? Math.max(0, nextReward.points_required - points) : 0; return <section className="points-wallet"><div><span className="eyebrow">REWARDS WALLET</span><strong>{points.toLocaleString()} <small>points</small></strong><p>{nextReward ? `${remaining.toLocaleString()} points until ${nextReward.name}.` : 'You can claim an available reward.'}</p></div><button className="button button-outline" onClick={onRewards}>View rewards <ArrowRight size={15} /></button></section> }
function NotificationPanel({ notifications }) { return <section className="notification-panel"><div className="notification-panel-head"><strong>Notifications</strong><small>{notifications.length ? 'Latest updates' : 'All caught up'}</small></div>{notifications.length ? <div className="notification-list">{notifications.slice(0, 6).map(notification => <article className={`notification-item ${notification.type || ''}`} key={notification.id}><Sparkles size={15} /><span><strong>{notification.title}</strong><small>{notification.message}</small></span></article>)}</div> : <div className="notification-empty">You have no notifications yet.</div>}</section> }
function QuickAction({ icon: Icon, label, onClick }) { return <button className="quick-action" onClick={onClick}><span><Icon size={19} /></span><strong>{label}</strong><ArrowRight size={15} /></button> }
function BillsTable({ bills, compact, onPaid, admin }) { return <div className="table-wrap"><table><thead><tr><th>Invoice</th><th>Customer</th><th>Service</th><th>Amount</th><th>Status</th>{admin && <th />}</tr></thead><tbody>{bills.map(bill => <tr key={bill.id}><td><strong>{bill.id}</strong><small>{bill.date}</small></td><td>{bill.customer}</td><td>{bill.service}</td><td><strong>₹{bill.amount.toLocaleString()}</strong></td><td><span className={`status ${bill.status.toLowerCase()}`}>{bill.status}</span></td>{admin && <td>{bill.status === 'Pending' && <button className="small-button" onClick={() => onPaid(bill.id)}>Mark paid</button>}</td>}</tr>)}</tbody></table></div> }
function BillsPage({ bills, notify, admin, onPaid, onBill }) { return <><PageHeader eyebrow={admin ? 'Finance desk' : 'Your documents'} title={admin ? 'Bills & payments' : 'My bills'} subtitle={admin ? 'Create invoices and keep payments moving.' : 'A clear record of every service at Dharma Motors.'} action={admin ? 'Create bill' : null} onAction={onBill} /><Panel title={admin ? 'All invoices' : 'Past services'}><BillsTable bills={bills} onPaid={onPaid} admin={admin} /><div className="table-mobile-hint">Swipe to view more details</div></Panel></> }
function BookingsPage({ bookings, onBook }) { return <><PageHeader eyebrow="Your vehicles, handled" title="My bookings" subtitle="Track every visit, from the first booking to pickup." action="Book appointment" onAction={onBook} /><Panel title="All appointments"><div className="booking-list expanded">{bookings.map(booking => <BookingRow key={booking.id} booking={booking} />)}</div></Panel></> }
function AppointmentsPage({ bookings, onWalkin, onAppointment }) { return <><PageHeader eyebrow="Front desk" title="Appointments" subtitle="Keep today's arrivals moving smoothly." action="Add walk-in" onAction={onWalkin} /><div className="filter-row"><button className="filter active">Today <span>{bookings.length}</span></button></div><Panel title="Appointments"><div className="booking-list expanded">{bookings.map(booking => <BookingRow key={booking.id} booking={booking} admin onAppointment={onAppointment} />)}{!bookings.length && <EmptyState text="No appointments yet." />}</div></Panel></> }
function JobsPage({ jobs, onJob, onBill }) { return <><PageHeader eyebrow="Workshop floor" title="Service jobs" subtitle="Move work through the shop with one clear status." action="Create bill" onAction={onBill} /><div className="job-board">{['Confirmed', 'Arrived', 'Completed'].map(status => <div className="job-column" key={status}><div className="column-heading"><span className={`status-dot ${status.toLowerCase()}`} /><h3>{status}</h3><b>{jobs.filter(job => job.status === status).length}</b></div>{jobs.filter(job => job.status === status).map(job => <div className="job-card" key={job.id}><div className="job-card-top"><strong>{job.id}</strong><button className="icon-button"><MoreHorizontal size={16} /></button></div><h4>{job.customer}</h4><p>{job.vehicle} · {job.issue}</p><small><Clock3 size={13} /> {job.time}</small><div className="job-actions">{status === 'Confirmed' && <button onClick={() => onJob(job.id, 'Arrived')}>Mark arrived</button>}{status === 'Arrived' && <button onClick={() => onJob(job.id, 'Completed')}>Complete job</button>}{status === 'Completed' && <button className="outline-action" onClick={() => onBill(job)}>Create bill</button>}</div></div>)}</div>)}</div></> }
function CustomersPage({ customers }) { return <><PageHeader eyebrow="Customer book" title="Customers" subtitle="Real customer profiles from Supabase." /><Panel title="Customers"><div className="customer-list">{customers.map(customer => <div className="customer-row" key={customer.id}><div className="avatar avatar-blue">{(customer.full_name || 'CU').split(' ').map(part => part[0]).join('').slice(0, 2)}</div><span><strong>{customer.full_name}</strong><small>{customer.phone} · Joined {new Date(customer.created_at).toLocaleDateString('en-IN')}{customer.referrer_name && ` · Referred by ${customer.referrer_name}`}</small></span><span className="customer-spend">{customer.points.toLocaleString()}<small>points</small></span><ChevronRight size={17} /></div>)}{!customers.length && <EmptyState text="No customers yet." />}</div></Panel></> }
function RewardsPage({ points, rewards = [], claims = [], notify, admin, onReward, onClaim }) { const [myClaims, setMyClaims] = useState([]); React.useEffect(() => { if (admin || !supabase) return undefined; let mounted = true; supabase.auth.getUser().then(({ data }) => data.user && supabase.from('reward_claims').select('id, claim_code, status, created_at, rewards(name, points_required)').eq('customer_id', data.user.id).order('created_at', { ascending: false }).then(({ data: result }) => { if (mounted) setMyClaims(result || []) })); return () => { mounted = false } }, [admin]); return <><PageHeader eyebrow={admin ? 'Retention engine' : 'Your loyalty wallet'} title={admin ? 'Rewards' : 'Rewards & points'} subtitle={admin ? 'Create rewards and see who claimed them.' : 'Every paid service brings you closer to something useful.'} action={admin ? 'Create reward' : null} onAction={onReward} />{!admin && <><div className="points-card"><div><span>AVAILABLE POINTS</span><strong>{points.toLocaleString()}</strong><small>points earned from paid services</small></div><div className="points-spark"><Sparkles size={31} /></div></div><CustomerClaimProof claims={myClaims} /></>}<div className="reward-grid">{rewards.map(reward => <div className="reward-card" key={reward.id}><div className="reward-icon"><Gift size={20} /></div><span className="reward-tag">LOYALTY REWARD</span><h3>{reward.name}</h3><p>{reward.description}</p><div className="reward-footer"><strong><Sparkles size={14} /> {reward.points_required.toLocaleString()} pts</strong>{!admin && <button className="small-button" onClick={() => onClaim(reward)}>Claim reward</button>}</div></div>)}{!rewards.length && <EmptyState text="No rewards available yet." />}</div>{admin && <Panel title="Recent reward claims"><div className="customer-list">{claims.map(claim => <div className="customer-row" key={claim.id}><div className="reward-icon"><Gift size={16} /></div><span><strong>{claim.profiles?.full_name || 'Customer'}</strong><small>{claim.rewards?.name || 'Reward'} · {new Date(claim.created_at).toLocaleDateString('en-IN')}<br /><b>Claim code: {claim.claim_code || 'Legacy claim'}</b></small></span><span className="customer-spend"><small>{claim.status}</small></span></div>)}{!claims.length && <EmptyState text="No reward claims yet." />}</div></Panel>}</> }
function CustomerClaimProof({ claims }) { return <section className="claim-proof"><div><span className="eyebrow">MY REWARD CLAIMS</span><h3>Show this code at Dharma Motors</h3><p>Staff will match the code to your reward claim before giving the benefit.</p></div>{claims.length ? <div className="claim-proof-list">{claims.map(claim => <div className="claim-proof-item" key={claim.id}><span><strong>{claim.rewards?.name || 'Reward'}</strong><small>{claim.status === 'fulfilled' ? 'Fulfilled' : 'Claimed — awaiting fulfilment'}</small></span><code>{claim.claim_code || 'Legacy claim'}</code></div>)}</div> : <small className="claim-proof-empty">No reward claims yet.</small>}</section> }
function ReferPage({ code, notify }) { const referralCode = code || 'Loading...'; return <><PageHeader eyebrow="Bring your people" title="Refer & earn" subtitle="Share your code. You earn 200 points and your friend earns 100 points after their first ₹500+ paid service." /><section className="referral-card"><div className="referral-copy"><span className="eyebrow light">YOUR REFERRAL CODE</span><strong>{referralCode}</strong><p>Your friend enters this code while creating their account. The bonus is automatic after their first qualifying payment.</p><button className="button button-light" onClick={() => { navigator.clipboard?.writeText(referralCode); notify('Referral code copied') }}>Copy code <Ticket size={16} /></button></div><div className="referral-art"><Users size={82} /></div></section><div className="referral-steps"><div><span>01</span><strong>Share your code</strong><p>Send your personal code to a friend.</p></div><div><span>02</span><strong>They register</strong><p>They enter it during signup.</p></div><div><span>03</span><strong>You both earn</strong><p>Points arrive after a ₹500+ paid bill.</p></div></div></> }
function SlotsPage({ slots = [], onSlot, onUpdateSlot }) { const [editing, setEditing] = useState(null); return <><PageHeader eyebrow="Capacity planning" title="Time slots" subtitle="Control the booking windows and capacity customers can use." action="Add time slot" onAction={onSlot} /><Panel title="Booking windows"><div className="slot-list">{slots.map(slot => <div className="slot-row" key={slot.id}><Clock3 size={17} /><strong>{slot.label}</strong><span>Max bookings <b>{slot.max_bookings}</b></span><button className={`toggle ${slot.enabled ? 'on' : ''}`} aria-label={`Toggle ${slot.label}`} onClick={() => onUpdateSlot(slot.id, { enabled: !slot.enabled })}><i /></button><button className="small-button" onClick={() => setEditing(slot)}>Edit</button></div>)}{!slots.length && <EmptyState text="No time slots created yet." />}</div></Panel>{editing && <Modal title="Edit time slot" onClose={() => setEditing(null)}><form onSubmit={async event => { event.preventDefault(); const form = new FormData(event.currentTarget); await onUpdateSlot(editing.id, { label: form.get('label'), max_bookings: Number(form.get('capacity')) }); setEditing(null) }}><Field label="Time slot"><input name="label" defaultValue={editing.label} required /></Field><Field label="Maximum bookings"><input name="capacity" type="number" min="1" defaultValue={editing.max_bookings} required /></Field><FormActions onCancel={() => setEditing(null)} submit="Save changes" /></form></Modal>}</> }
function EmptyState({ text }) { return <div className="empty-state">{text}</div> }
function DatabaseSetupState({ onRetry }) { return <section className="setup-state"><Database size={28} /><h2>We’re updating your account</h2><p>Your workshop information is temporarily unavailable. Please try again in a moment.</p><button className="button button-primary" onClick={onRetry}>Try again</button></section> }
function WalkinPage({ notify, onCreate }) { return <><PageHeader eyebrow="Front desk" title="Walk-in customer" subtitle="Save the intake first, then turn it into a customer profile and job." /><div className="walkin-layout"><Panel title="Customer details"><form onSubmit={event => { event.preventDefault(); const form = new FormData(event.currentTarget); onCreate({ full_name: form.get('name'), phone: form.get('phone'), vehicle_model: form.get('model'), vehicle_type: form.get('type'), fuel: form.get('fuel'), notes: form.get('notes') }) }}><Field label="Full name"><input name="name" placeholder="Customer name" required /></Field><Field label="Mobile number"><input name="phone" inputMode="tel" placeholder="10-digit mobile number" required /></Field><div className="form-divider" /><h4>Vehicle details</h4><Field label="Model name"><input name="model" placeholder="e.g. Tata Nexon" required /></Field><div className="form-grid"><Field label="Type"><select name="type"><option value="car">Car</option><option value="suv">SUV</option><option value="truck">Truck</option></select></Field><Field label="Fuel"><select name="fuel"><option value="petrol">Petrol</option><option value="diesel">Diesel</option></select></Field></div><Field label="Notes (optional)"><textarea name="notes" placeholder="Problem reported by customer" /></Field><button className="button button-primary full-button" type="submit">Save walk-in intake <ArrowRight size={16} /></button></form></Panel><div className="walkin-note"><Zap size={20} /><h3>Fast lane for the front desk</h3><p>This saves the walk-in request in Supabase. Create the Auth profile later if the customer wants portal access.</p></div></div></> }
function Field({ label, children }) { return <label className="field"><span>{label}</span>{children}</label> }
function FormActions({ onCancel, submit }) { return <div className="form-actions"><button className="button button-quiet" type="button" onClick={onCancel}>Cancel</button><button className="button button-primary" type="submit">{submit} <ArrowRight size={16} /></button></div> }
function Modal({ title, onClose, children }) { return <div className="modal-backdrop" onMouseDown={onClose}><div className="modal" onMouseDown={event => event.stopPropagation()}><div className="modal-heading"><h2>{title}</h2><button className="icon-button" onClick={onClose}><X size={18} /></button></div>{children}</div></div> }

createRoot(document.getElementById('root')).render(<StrictMode><App /></StrictMode>)

if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => navigator.serviceWorker.register('/sw.js').catch(() => {}))
}
